package main

import "fmt"

func main() {
	ch := make(chan int, 1)
	ch <- 7
	close(ch)
	v, ok := <-ch // drains the buffered value
	fmt.Println(v, ok)
	v, ok = <-ch // now closed & drained
	fmt.Println(v, ok)
	// Output:
	// 7 true
	// 0 false
}

