package main

import "fmt"

func produce(n int) <-chan int {
	ch := make(chan int)
	go func() {
		for i := 1; i <= n; i++ {
			ch <- i            // each send blocks until main receives
		}
		close(ch)              // signal 'no more values' so range ends
	}()
	return ch
}

func main() {
	sum := 0
	for v := range produce(4) {  // receives until ch is closed & drained
		sum += v
	}
	fmt.Println(sum)             // 1+2+3+4 = 10
}

