package solution

func Solve(nums []int) []int {
	in := make(chan int)
	go func() {                 // producer
		for _, n := range nums {
			in <- n
		}
		close(in)               // no more inputs
	}()

	out := make(chan int)
	go func() {                 // doubling stage
		for n := range in {     // drains in until closed
			out <- n * 2
		}
		close(out)              // no more outputs
	}()

	res := make([]int, 0, len(nums))
	for v := range out {        // collect in send order
		res = append(res, v)
	}
	return res
}

