func Merge(a, b <-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	copyCh := func(c <-chan int) {
		defer wg.Done()
		for v := range c { // drain c until closed
			out <- v
		}
	}
	wg.Add(2)
	go copyCh(a)
	go copyCh(b)
	go func() { wg.Wait(); close(out) }() // one owner closes once
	return out
}

func WorkerPool(jobs []int, workers int, do func(int) int) []int {
	type item struct {
		idx, val int
	}
	in := make(chan item)
	out := make(chan item)

	go func() { // feed indexed jobs
		for i, j := range jobs {
			in <- item{i, j}
		}
		close(in) // no more jobs
	}()

	var wg sync.WaitGroup
	wg.Add(workers)
	for w := 0; w < workers; w++ {
		go func() {
			defer wg.Done()
			for it := range in { // drain shared jobs channel
				out <- item{it.idx, do(it.val)}
			}
		}()
	}

	go func() { wg.Wait(); close(out) }() // single owner closes once

	res := make([]int, len(jobs))
	for it := range out { // reassemble by original index
		res[it.idx] = it.val
	}
	return res
}
